"""Expression Add Operators — backtracking that carries the last operand.

Multiplication binds tighter than the running total, so the previously added
term is undone and re-applied: total - prev + prev * current.

Time: O(4^n)   Space: O(n)
"""
from typing import List


class Solution:
    def addOperators(self, num: str, target: int) -> List[str]:
        out = []

        def walk(index: int, expression: str, total: int, prev: int) -> None:
            if index == len(num):
                if total == target:
                    out.append(expression)
                return
            for end in range(index + 1, len(num) + 1):
                piece = num[index:end]
                if len(piece) > 1 and piece[0] == "0":
                    break                      # no leading zeros
                value = int(piece)
                if index == 0:
                    walk(end, piece, value, value)
                else:
                    walk(end, expression + "+" + piece, total + value, value)
                    walk(end, expression + "-" + piece, total - value, -value)
                    walk(end, expression + "*" + piece,
                         total - prev + prev * value, prev * value)

        walk(0, "", 0, 0)
        return out
